import{_ as d,a0 as p,w as n,s as o,ao as c,I as l,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"使用 fdisk 和 fallocate 命令創建交換分區 | LCTT x X-CMD","titleTemplate":false,"description":"使用 fdisk 和 fallocate 命令創建交換分區 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 fdisk 和 fallocate 命令創建交換分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 fdisk 和 fallocate 命令創建交換分區 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170802 Creating SWAP partition using FDISK - FALLOCATE commands","title":"使用 fdisk 和 fallocate 命令創建交換分區","tag":"201801","desc":""},"relativePath":"201801/20170802 Creating SWAP partition using FDISK - FALLOCATE commands.md","filePath":"[post].md"}'),h={name:"201801/20170802 Creating SWAP partition using FDISK - FALLOCATE commands.md"};function r(g,s,k,f,u,b){const e=p("Link");return n(),o("div",null,[s[13]||(s[13]=c(`<h1 id="使用-fdisk-和-fallocate-命令創建交換分區" tabindex="-1">使用 fdisk 和 fallocate 命令創建交換分區 <a class="header-anchor" href="#使用-fdisk-和-fallocate-命令創建交換分區" aria-label="Permalink to “使用 fdisk 和 fallocate 命令創建交換分區”">​</a></h1><p>交換分區在物理內存（RAM）被填滿時用來保持內存中的內容。當 RAM 被耗盡，Linux 會將內存中不活動的頁移動到交換空間中，從而空出內存給系統使用。雖然如此，但交換空間不應被認為是物理內存的替代品。</p><p>大多數情況下，建議交換內存的大小為物理內存的 1 到 2 倍。也就是説如果你有 8GB 內存, 那麼交換空間大小應該介於8-16 GB。</p><p>若系統中沒有配置交換分區，當內存耗盡後，系統可能會殺掉正在運行中的進程/應用，從而導致系統崩潰。在本文中，我們將學會如何為 Linux 系統添加交換分區，我們有兩個辦法：</p><ul><li>使用 fdisk 命令</li><li>使用 fallocate 命令</li></ul><h3 id="第一個方法-使用-fdisk-命令" tabindex="-1">第一個方法（使用 fdisk 命令） <a class="header-anchor" href="#第一個方法-使用-fdisk-命令" aria-label="Permalink to “第一個方法（使用 fdisk 命令）”">​</a></h3><p>通常，系統的第一塊硬盤會被命名為 <code>/dev/sda</code>，而其中的分區會命名為 <code>/dev/sda1</code> 、 <code>/dev/sda2</code>。 本文我們使用的是一塊有兩個主分區的硬盤，兩個分區分別為 <code>/dev/sda1</code>、 <code>/dev/sda2</code>，而我們使用 <code>/dev/sda3</code> 來做交換分區。</p><p>首先創建一個新分區，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdisk /dev/sda</span></span></code></pre></div><p>按 <code>n</code> 來創建新分區。系統會詢問你從哪個柱面開始，直接按回車鍵使用默認值即可。然後系統詢問你到哪個柱面結束, 這裏我們輸入交換分區的大小（比如 1000MB）。這裏我們輸入 <code>+1000M</code>。</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/fidsk.jpg?resize=668%2C211" alt="swap"></p><p>現在我們創建了一個大小為 1000MB 的磁盤了。但是我們並沒有設置該分區的類型，我們按下 <code>t</code> 然後回車，來設置分區類型。</p><p>現在我們要輸入分區編號，這裏我們輸入 <code>3</code>，然後輸入磁盤分類號，交換分區的分區類型為 <code>82</code> （要顯示所有可用的分區類型，按下 <code>l</code> ) ，然後再按下 <code>w</code> 保存磁盤分區表。</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/fidsk-swap-select.jpg?resize=620%2C157" alt="swap"></p><p>再下一步使用 <code>mkswap</code> 命令來格式化交換分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkswap /dev/sda3</span></span></code></pre></div><p>然後激活新建的交換分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon /dev/sda3</span></span></code></pre></div><p>然而我們的交換分區在重啓後並不會自動掛載。要做到永久掛載，我們需要添加內容到 <code>/etc/fstab</code> 文件中。打開 <code>/etc/fstab</code> 文件並輸入下面行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda3 swap  swap  default  0  0</span></span></code></pre></div><p>保存並關閉文件。現在每次重啓後都能使用我們的交換分區了。</p><h3 id="第二種方法-使用-fallocate-命令" tabindex="-1">第二種方法（使用 fallocate 命令） <a class="header-anchor" href="#第二種方法-使用-fallocate-命令" aria-label="Permalink to “第二種方法（使用 fallocate 命令）”">​</a></h3><p>我推薦用這種方法因為這個是最簡單、最快速的創建交換空間的方法了。<code>fallocate</code> 是最被低估和使用最少的命令之一了。 <code>fallocate</code> 命令用於為文件預分配塊/大小。</p><p>使用 <code>fallocate</code> 創建交換空間，我們首先在 <code>/</code> 目錄下創建一個名為 <code>swap_space</code> 的文件。然後分配 2GB 到 <code>swap_space</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fallocate -l 2G /swap_space</span></span></code></pre></div><p>我們運行下面命令來驗證文件大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh /swap_space</span></span></code></pre></div><p>然後更改文件權限，讓 <code>/swap_space</code> 更安全：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 600 /swap_space</span></span></code></pre></div><p>這樣只有 root 可以讀寫該文件了。我們再來格式化交換分區（LCTT 譯註：雖然這個 <code>swap_space</code> 是個文件，但是我們把它當成是分區來掛載）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkswap /swap_space</span></span></code></pre></div><p>然後啓用交換空間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon -s</span></span></code></pre></div><p>每次重啓後都要重新掛載磁盤分區。因此為了使之持久化，就像上面一樣，我們編輯 <code>/etc/fstab</code> 並輸入下面行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/swap_space swap  swap  sw  0  0</span></span></code></pre></div><p>保存並退出文件。現在我們的交換分區會一直被掛載了。我們重啓後可以在終端運行 <code>free -m</code> 來檢查交換分區是否生效。</p><p>我們的教程至此就結束了，希望本文足夠容易理解和學習，如果有任何疑問歡迎提出。</p><hr>`,38)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"http://linuxtechlab.com/create-swap-using-fdisk-fallocate/"},{default:t(()=>[...s[0]||(s[0]=[a("http://linuxtechlab.com/create-swap-using-fdisk-fallocate/",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=a("作者：",-1)),i(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...s[2]||(s[2]=[a("Shusain",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const w=d(h,[["render",r]]);export{v as __pageData,w as default};
